import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.gExYLvYZ.js";const u=JSON.parse('{"title":"Evaluate Hookshot","description":"Feature matrix, boundaries, and decision criteria for evaluating hookshot","frontmatter":{"title":"Evaluate Hookshot","description":"Feature matrix, boundaries, and decision criteria for evaluating hookshot","audience":["evaluator","architect"]},"headers":[],"relativePath":"get-started/evaluate.md","filePath":"get-started/evaluate.md","lastUpdated":1775243555000}'),r={name:"get-started/evaluate.md"};function i(d,t,n,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="evaluate-hookshot" tabindex="-1">Evaluate Hookshot <a class="header-anchor" href="#evaluate-hookshot" aria-label="Permalink to &quot;Evaluate Hookshot&quot;">​</a></h1><p>This page helps you decide if hookshot fits your needs. No setup required — just information.</p><h2 id="what-hookshot-does-well" tabindex="-1">What hookshot does well <a class="header-anchor" href="#what-hookshot-does-well" aria-label="Permalink to &quot;What hookshot does well&quot;">​</a></h2><ul><li><strong>Multi-service integration in one deployment.</strong> One appservice bridges GitHub, GitLab, JIRA, webhooks, feeds, Figma, and OpenProject. No separate bot per service.</li><li><strong>Configuration via Matrix rooms.</strong> Connections are stored as room state events. No external database. Config travels with rooms, survives room upgrades, works with federation.</li><li><strong>Extensible webhook handling.</strong> Generic webhooks with JavaScript transformation functions let you integrate any service that can send HTTP.</li><li><strong>Fine-grained permissions.</strong> Per-user, per-service, per-domain permission control. Different teams can have different access levels.</li><li><strong>Production-ready.</strong> Prometheus metrics, Sentry integration, Redis caching, worker scaling, E2EE support.</li></ul><h2 id="what-hookshot-does-not-do" tabindex="-1">What hookshot does NOT do <a class="header-anchor" href="#what-hookshot-does-not-do" aria-label="Permalink to &quot;What hookshot does NOT do&quot;">​</a></h2><ul><li><strong>Full conversation sync.</strong> Hookshot delivers notifications and accepts commands. It does not mirror entire chat histories between Matrix and Slack/Discord/etc. For that, use <a href="https://github.com/matrix-org/matrix-appservice-slack" target="_blank" rel="noreferrer">matrix-appservice-slack</a> or <a href="https://mau.fi/bridges/" target="_blank" rel="noreferrer">mautrix bridges</a>.</li><li><strong>Bidirectional issue sync.</strong> Hookshot can create issues on external services and receive notifications. It does not keep issues synchronized between services.</li><li><strong>Custom bot logic.</strong> Hookshot has fixed integration logic. For custom bot behavior, use <a href="https://github.com/turt2live/matrix-bot-sdk" target="_blank" rel="noreferrer">matrix-bot-sdk</a> directly.</li><li><strong>Multi-homeserver deployment.</strong> One hookshot instance connects to one homeserver.</li></ul><h2 id="capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>GitHub</th><th>GitLab</th><th>JIRA</th><th>Webhooks</th><th>Feeds</th><th>Figma</th><th>OpenProject</th><th>ChallengeHound</th></tr></thead><tbody><tr><td>Receive notifications</td><td>23 events</td><td>12 events</td><td>5 events</td><td>Any payload</td><td>New entries</td><td>Comments</td><td>Work packages</td><td>Activities</td></tr><tr><td>Bot commands</td><td>4</td><td>3</td><td>3</td><td>—</td><td>—</td><td>—</td><td>5</td><td>—</td></tr><tr><td>OAuth</td><td>GitHub App + user</td><td>Token</td><td>Cloud OAuth 2.0, Server OAuth 1.0</td><td>—</td><td>—</td><td>—</td><td>OAuth 2.0</td><td>—</td></tr><tr><td>Webhook-based</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>No (polling)</td><td>Yes</td><td>Yes</td><td>No (polling)</td></tr><tr><td>Widget UI</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Dynamic rooms</td><td>Yes</td><td>Yes</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Enterprise/self-hosted</td><td>Yes</td><td>Yes</td><td>Yes (Cloud + Server)</td><td>N/A</td><td>N/A</td><td>N/A</td><td>Yes</td><td>N/A</td></tr></tbody></table><h2 id="deployment-requirements" tabindex="-1">Deployment requirements <a class="header-anchor" href="#deployment-requirements" aria-label="Permalink to &quot;Deployment requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td>Homeserver</td><td>Synapse, Dendrite, or Conduit with appservice support</td></tr><tr><td>Runtime</td><td>Node.js 22+ with Rust native modules (or Docker)</td></tr><tr><td>Memory</td><td>~100 MB baseline, grows with room count</td></tr><tr><td>Storage</td><td>Encrypted token file (passkey.pem). Optional: Redis for caching</td></tr><tr><td>Network</td><td>Outbound: homeserver API. Inbound: webhook endpoints (must be public for webhook services)</td></tr><tr><td>Database</td><td>None — Matrix room state is the primary store</td></tr></tbody></table><h2 id="comparison-with-alternatives" tabindex="-1">Comparison with alternatives <a class="header-anchor" href="#comparison-with-alternatives" aria-label="Permalink to &quot;Comparison with alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Hookshot</th><th>Standalone bots</th><th>Custom appservice</th></tr></thead><tbody><tr><td>Multi-service</td><td>8 services in one</td><td>One bot per service</td><td>Build your own</td></tr><tr><td>Setup complexity</td><td>Medium (config + registration)</td><td>Low per bot</td><td>High</td></tr><tr><td>Matrix-native storage</td><td>Yes (room state)</td><td>Usually external DB</td><td>Your choice</td></tr><tr><td>Permission system</td><td>Built-in, fine-grained</td><td>Per-bot</td><td>Build your own</td></tr><tr><td>Webhook transformation</td><td>JavaScript sandbox</td><td>Custom code</td><td>Custom code</td></tr><tr><td>Maintenance</td><td>One deployment</td><td>N deployments</td><td>Your code</td></tr></tbody></table><h2 id="architecture-fit" tabindex="-1">Architecture fit <a class="header-anchor" href="#architecture-fit" aria-label="Permalink to &quot;Architecture fit&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light tokyo-night vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────┐</span></span>
<span class="line"><span>│   Matrix Homeserver  │</span></span>
<span class="line"><span>│   (Synapse/Dendrite) │</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│  Appservice API      │◄──── Hookshot registers here</span></span>
<span class="line"><span>└──────────┬──────────┘</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>    ┌──────▼──────┐</span></span>
<span class="line"><span>    │   Hookshot   │◄──── Single process (or workers)</span></span>
<span class="line"><span>    │              │      No external DB required</span></span>
<span class="line"><span>    └──┬───┬───┬──┘      Optional: Redis cache</span></span>
<span class="line"><span>       │   │   │</span></span>
<span class="line"><span>       ▼   ▼   ▼</span></span>
<span class="line"><span>    GitHub GitLab JIRA ... (webhook endpoints)</span></span></code></pre></div><p>Hookshot adds ~100 MB memory overhead to your Matrix deployment. It communicates with the homeserver over HTTP (appservice API). External services reach hookshot over HTTP (webhooks).</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>JIRA Server reached EOL February 2024. Hookshot still supports it but the <code>jira-client</code> package is unmaintained.</li><li><code>figma-js</code> package is unmaintained (pre-release pin). Figma integration works but the dependency is a risk.</li><li>Generic webhooks have no signature verification — URL secrecy is the only protection.</li><li>No built-in rate limiting for outbound API calls.</li><li>Room state as storage means no cross-room queries (e.g., &quot;list all GitHub connections&quot;).</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to...</th><th>Go to</th></tr></thead><tbody><tr><td>Try it now</td><td><a href="./quickstart">Quickstart</a></td></tr><tr><td>Understand the architecture</td><td><a href="./../understand/what-is-hookshot">What is Hookshot</a></td></tr><tr><td>See all integrations</td><td><a href="./../integrations/overview">Integration Overview</a></td></tr><tr><td>Plan a production deployment</td><td><a href="./../guides/operator/installation">Installation</a></td></tr><tr><td>Understand the security model</td><td><a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../understand/what-is-hookshot">What is Hookshot</a> — System overview</li><li><a href="./../integrations/overview">Integration Overview</a> — All capabilities</li><li><a href="./../architecture/connections">Architecture: Connections</a> — How it works inside</li></ul>`,21)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
